import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

conv_transpose3d_source = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void conv_transpose3d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    const int batch_size,
    const int in_channels,
    const int out_channels,
    const int in_d, const int in_h, const int in_w,
    const int out_d, const int out_h, const int out_w,
    const int kernel_size,
    const int stride,
    const int padding,
    const int groups,
    const int in_channels_per_group,
    const int out_channels_per_group,
    const bool has_bias)
{
    // Each block handles one (batch, out_channel) pair and a tile of spatial
    // output positions. The weight slice needed for this out_channel is
    // cooperatively staged into shared memory once per block, drastically
    // reducing redundant global memory loads of the (reused) weights.
    extern __shared__ float s_weight[];
    int bc = blockIdx.y;
    int oc = bc % out_channels;
    int b = bc / out_channels;
    int g = oc / out_channels_per_group;
    int oc_local = oc % out_channels_per_group;
    int ic_start = g * in_channels_per_group;
    const int k3 = kernel_size * kernel_size * kernel_size;
    const int weight_slice_size = in_channels_per_group * k3;
    for (int i = threadIdx.x; i < weight_slice_size; i += blockDim.x) {
        int ic_local = i / k3;
        int rem = i % k3;
        int ic = ic_start + ic_local;
        long long weight_idx = (((long long)ic * out_channels_per_group + oc_local) * k3) + rem;
        s_weight[i] = weight[weight_idx];
    }
    __syncthreads();
    long long spatial_total = (long long)out_d * out_h * out_w;
    long long spatial_idx = blockIdx.x * (long long)blockDim.x + threadIdx.x;
    if (spatial_idx >= spatial_total) return;
    int ow = spatial_idx % out_w;
    long long tmp = spatial_idx / out_w;
    int oh = tmp % out_h;
    tmp = tmp / out_h;
    int od = tmp;
    float sum = 0.0f;
    for (int ic_local = 0; ic_local < in_channels_per_group; ic_local++) {
        int ic = ic_start + ic_local;
        for (int kd = 0; kd < kernel_size; kd++) {
            int id_num = od + padding - kd;
            if (id_num % stride != 0) continue;
            int id_val = id_num / stride;
            if (id_val < 0 || id_val >= in_d) continue;
            for (int kh = 0; kh < kernel_size; kh++) {
                int ih_num = oh + padding - kh;
                if (ih_num % stride != 0) continue;
                int ih_val = ih_num / stride;
                if (ih_val < 0 || ih_val >= in_h) continue;
                for (int kw = 0; kw < kernel_size; kw++) {
                    int iw_num = ow + padding - kw;
                    if (iw_num % stride != 0) continue;
                    int iw_val = iw_num / stride;
                    if (iw_val < 0 || iw_val >= in_w) continue;
                    long long input_idx = (((long long)b * in_channels + ic) * in_d + id_val) * in_h * in_w
                                           + (long long)ih_val * in_w + iw_val;
                    int s_idx = ic_local * k3 + kd * kernel_size * kernel_size + kh * kernel_size + kw;
                    sum += input[input_idx] * s_weight[s_idx];
                }
            }
        }
    }
    if (has_bias) {
        sum += bias[oc];
    }
    long long out_idx = (((long long)b * out_channels + oc) * out_d + od) * out_h * out_w
                         + (long long)oh * out_w + ow;
    output[out_idx] = sum;
}
torch::Tensor conv_transpose3d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int padding,
    int output_padding,
    int groups,
    bool has_bias)
{
    input = input.contiguous();
    weight = weight.contiguous();
    const int batch_size = input.size(0);
    const int in_channels = input.size(1);
    const int in_d = input.size(2);
    const int in_h = input.size(3);
    const int in_w = input.size(4);
    const int kernel_size = weight.size(2);
    const int out_channels_per_group = weight.size(1);
    const int out_channels = out_channels_per_group * groups;
    const int in_channels_per_group = in_channels / groups;
    const int out_d = (in_d - 1) * stride - 2 * padding + kernel_size + output_padding;
    const int out_h = (in_h - 1) * stride - 2 * padding + kernel_size + output_padding;
    const int out_w = (in_w - 1) * stride - 2 * padding + kernel_size + output_padding;
    auto output = torch::zeros({batch_size, out_channels, out_d, out_h, out_w}, input.options());
    long long spatial_total = (long long)out_d * out_h * out_w;
    const int threads = 256;
    const long long blocks_x = (spatial_total + threads - 1) / threads;
    const long long blocks_y = (long long)batch_size * out_channels;
    dim3 grid((unsigned int)blocks_x, (unsigned int)blocks_y, 1);
    dim3 block(threads, 1, 1);
    const int k3 = kernel_size * kernel_size * kernel_size;
    const size_t shared_mem_size = (size_t)in_channels_per_group * k3 * sizeof(float);
    const float* bias_ptr = nullptr;
    if (has_bias) {
        bias = bias.contiguous();
        bias_ptr = bias.data_ptr<float>();
    }
    conv_transpose3d_kernel<<<grid, block, shared_mem_size>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias_ptr,
        output.data_ptr<float>(),
        batch_size,
        in_channels,
        out_channels,
        in_d, in_h, in_w,
        out_d, out_h, out_w,
        kernel_size,
        stride,
        padding,
        groups,
        in_channels_per_group,
        out_channels_per_group,
        has_bias
    );
    return output;
}
'''

conv_transpose3d_header = r'''
torch::Tensor conv_transpose3d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int padding,
    int output_padding,
    int groups,
    bool has_bias);
'''

conv_transpose3d_module = load_inline(
    name='conv_transpose3d_module',
    cpp_sources=conv_transpose3d_header,
    cuda_sources=conv_transpose3d_source,
    functions=['conv_transpose3d_cuda'],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Performs a transposed 3D convolution with square input and square kernel,
    using a custom CUDA kernel.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, output_padding: int = 0, groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.output_padding = output_padding
        self.groups = groups
        self.has_bias = bias

        # Weight shape matching nn.ConvTranspose3d: (in_channels, out_channels/groups, kD, kH, kW)
        self.weight = nn.Parameter(torch.empty(in_channels, out_channels // groups, kernel_size, kernel_size, kernel_size))
        if bias:
            self.bias = nn.Parameter(torch.empty(out_channels))
        else:
            self.register_parameter('bias', None)

        self.reset_parameters()

    def reset_parameters(self):
        nn.init.kaiming_uniform_(self.weight, a=5**0.5)
        if self.bias is not None:
            fan_in = self.in_channels
            bound = 1 / (fan_in ** 0.5) if fan_in > 0 else 0
            nn.init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x = x.cuda().contiguous()
        weight = self.weight.cuda().contiguous()
        bias_tensor = self.bias.cuda().contiguous() if self.has_bias else torch.empty(0, device=x.device)

        return conv_transpose3d_module.conv_transpose3d_cuda(
            x, weight, bias_tensor,
            self.stride, self.padding, self.output_padding, self.groups, self.has_bias
        )

